export function getNLMLAProfile(acNo: number): MLAProfile | undefined {
  return NL_MLA_PROFILES.find(p => p.acNo === acNo);
}

export function getNLMLAsByParty(party: string): MLAProfile[] {
  return NL_MLA_PROFILES.filter(p => p.party === party);
}

export function getNLFemaleMLAs(): MLAProfile[] {
  return NL_MLA_PROFILES.filter(p => p.gender === 'F');
}
